function runCode() {
    const resultArea = document.getElementById('result-area');
    const resultCard = document.getElementById('result-card');
    const resultIcon = document.getElementById('result-icon');
    const resultTitle = document.getElementById('result-title');
    const resultMsg = document.getElementById('result-msg');
    const nextBtn = document.getElementById('next-btn');

    // Simulate random outcome
    const isSuccess = Math.random() > 0.4;

    resultArea.classList.remove('hidden');

    if (isSuccess) {
        resultCard.className = "bg-surface-container rounded-xl p-6 border-2 border-primary-container transition-all";
        resultIcon.src = "https://lh3.googleusercontent.com/aida/ADBb0ujeVAqBbSd3diS720e944UnAwigrjL4WGUDmvbzxJZRjTe7m5FrVazNHHYNuZvGhE46zQpKbyVQ5IzckOd7_kOQvq1AA5OKCi5RuV-iU_MPTobCS_7U2m79sjVy1bb4rUJ-S5EBtE0yVpB55ioTl_ITKNEXidLFofwGT1eRZceGPARD-5uHvgtpkbRsSgQMOVV4kZ6uizlNjgxPrUl69EtJ2LlgLwUu3PieaZpCSfzzGHe0Z_OdXROFhRLm";
        resultTitle.innerText = "Tuyệt vời!";
        resultMsg.innerText = "Tất cả các trường hợp kiểm thử (test cases) đều đã vượt qua thành công.";
        nextBtn.classList.remove('hidden');
    } else {
        resultCard.className = "bg-surface-container rounded-xl p-6 border-2 border-error/30 transition-all";
        resultIcon.src = "https://lh3.googleusercontent.com/aida/ADBb0ujIDI3MDegsMqgaxhy6tMnz56YBi2afJnLjxeDR34XOoz6IOTs0qCdl8fMNojtPdauzF9S7Oj-2l-ciBS8_t17FaSdZ9BpdiOAop_QfDwECtVO-QVOMjHICeERZpI0mL8DikQrNYjnMqIET7xufLE72b48UePZUffWx7PBSiVcLXgGjZdQed6666M9ys51Nan615zi6QjJ0JrJIXC2nsmOq8gKgQgMQrj8MY_6Al6ZJKwMnkWeZK4Sj3Zhb";
        resultTitle.innerText = "Opps! Lỗi rồi";
        resultMsg.innerText = "Hàm của bạn trả về 'undefined' cho đầu vào 'Hello'. Hãy kiểm tra lại logic.";
        nextBtn.classList.add('hidden');
    }

    window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
}

function hideResult() {
    document.getElementById('result-area').classList.add('hidden');
}
